# Let me do everything in one clean script
from itertools import combinations
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

n = 23
edges_list = [(u, v) for u in range(n) for v in range(u+1, n)]
edge_to_var = {(u,v): i+1 for i, (u,v) in enumerate(edges_list)}

def get_var(u, v):
    if u > v: u, v = v, u
    return edge_to_var[(u,v)]

cnf_clauses = []
top_var = len(edges_list)

# Degree constraints: 3 <= deg(v) <= 4
for v in range(n):
    neighbor_vars = [get_var(v, u) for u in range(n) if u != v]
    atmost = CardEnc.atmost(lits=neighbor_vars, bound=4, encoding=EncType.seqcounter, top_id=top_var)
    top_var = atmost.nv
    atleast = CardEnc.atleast(lits=neighbor_vars, bound=3, encoding=EncType.seqcounter, top_id=top_var)
    top_var = atleast.nv
    for clause in atmost.clauses: cnf_clauses.append(clause)
    for clause in atleast.clauses: cnf_clauses.append(clause)

# No C3
for a, b, c in combinations(range(n), 3):
    cnf_clauses.append([-get_var(a,b), -get_var(b,c), -get_var(a,c)])

# No C4: for all distinct a,b,c,d: not(a-b and b-c and c-d and a-d)
# We enumerate ordered paths a->b->c->d and require not(edge a-d) when a<d
for b in range(n):
    for a in range(n):
        if a == b: continue
        for c in range(n):
            if c in (a, b): continue
            for d in range(n):
                if d in (a, b, c): continue
                if a < d:
                    cnf_clauses.append([-get_var(a,b), -get_var(b,c), -get_var(c,d), -get_var(a,d)])

print(f"After C3+C4: {len(cnf_clauses)} clauses, top_var={top_var}")

# Add C5 constraints: no 5-cycles
# For all distinct a,b,c,d,e: not(a-b and b-c and c-d and d-e and a-e)
count_c5 = 0
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c in (a, b): continue
            for d in range(n):
                if d in (a, b, c): continue
                for e in range(n):
                    if e in (a, b, c, d): continue
                    if a < e:  # canonical: a is smallest endpoint
                        cnf_clauses.append([-get_var(a,b), -get_var(b,c), -get_var(c,d), -get_var(d,e), -get_var(a,e)])
                        count_c5 += 1

print(f"C5 clauses: {count_c5}, total: {len(cnf_clauses)}")
